package com.trainflow.document;
import java.io.*; import java.util.Map; import org.apache.pdfbox.pdmodel.*; import org.apache.pdfbox.pdmodel.font.Standard14Fonts; import org.apache.pdfbox.pdmodel.font.PDType1Font; import org.springframework.stereotype.Component;
@Component public class PdfRenderer {public byte[] render(DocumentType type,Map<String,Object> snapshot)throws IOException{try(var pdf=new PDDocument();var out=new ByteArrayOutputStream()){var page=new PDPage();pdf.addPage(page);try(var stream=new PDPageContentStream(pdf,page)){var font=new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD);stream.beginText();stream.setFont(font,18);stream.newLineAtOffset(55,760);stream.showText(title(type));stream.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),11);stream.newLineAtOffset(0,-30);stream.showText(safe("Reference: "+snapshot.get("reference")));stream.newLineAtOffset(0,-20);stream.showText(safe("Theme: "+snapshot.get("theme")));stream.newLineAtOffset(0,-20);stream.showText(safe("TrainFlow AI - document generated locally"));stream.endText();}pdf.save(out);return out.toByteArray();}}private static String title(DocumentType t){return switch(t){case PROGRAM->"Training program";case QUOTE->"Quotation";case AGREEMENT->"Training agreement";case ATTENDANCE_SHEET->"Attendance sheet";case CERTIFICATE->"Training certificate";};}private static String safe(String value){return value.replaceAll("[^\\x20-\\x7E]","?");}}
